use std :: collections :: { BTreeSet , HashMap } ; use std :: path :: { Path , PathBuf } ; use forge_domain :: { FileHash , FileStatus , SyncProgress , SyncStatus } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Joins `base_dir` with `path` if `path` is relative, returning an absolute"] # [doc = " path string. If `path` is already absolute it is returned unchanged."] fn absolutize (base_dir : & Path , path : & str) -> String { let p = Path :: new (path) ; if p . is_absolute () { path . to_owned () } else { base_dir . join (p) . to_string_lossy () . into_owned () } }